// Worker entry: the OpenNext-generated Next.js handler plus a cron trigger that
// replaces the Vercel cron. The cron calls the existing protected cleanup route
// with the same Bearer secret Vercel used, so the route itself is unchanged.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; CLEANUP_SECRET?: string; NEXT_PUBLIC_APP_URL?: string };

const CRON_ROUTES: Record<string, string> = {
  "0 2 * * *": "/api/cleanup-expired-files",
};

export default {
  fetch: handler.fetch,

  async scheduled(event: ScheduledController, env: Env, ctx: ExecutionContext) {
    const path = CRON_ROUTES[event.cron];
    const secret = env.CRON_SECRET || env.CLEANUP_SECRET;
    if (!path || !secret) {
      console.error("Cron skipped:", event.cron, path ? "no secret" : "unknown schedule");
      return;
    }
    const request = new Request(new URL(path, "https://boltshare.rcinc.app"), {
      headers: { authorization: `Bearer ${secret}` },
    });
    const response = await handler.fetch(request, env, ctx);
    console.log("Cron", event.cron, path, response.status, await response.text());
  },
} satisfies ExportedHandler<Env>;

// @ts-ignore -- re-export Durable Object classes OpenNext may generate
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
